                  class="form-control cover-letter-input"
                  rows="12"
                  maxlength="@MaxLength"
                  placeholder="Write your cover letter here..."></textarea>
        <span class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-summary">@ValidationMessage</div>
    }

    <div class="step-actions">
