{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_4464c9df3eb9451b90016a922c8bf8ab.Models
@using static WorkEntryForm
@using static ReferenceForm
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received successfully.</p>
            <p class="application-id">Application ID: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@CurrentStep" OnStepClicked="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@PersonalFullName"
                                  Email="@PersonalEmail"
                                  Phone="@PersonalPhone"
                                  Address="@PersonalAddress"
                                  ValidateEmail="ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="@WorkEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="HandleWorkBack" />
                break;
            case 2:
                <ReferencesStep References="@ReferenceEntries"
                                OnNext="HandleReferencesNext"
                                OnBack="HandleReferencesBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@CoverLetterText"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="HandleCoverLetterBack" />
                break;
            case 4:
                <ReviewStep Personal="@GetPersonalResult()"
                            WorkEntries="@WorkEntries"
                            References="@ReferenceEntries"
                            CoverLetter="@CoverLetterText"
                            OnBack="() => CurrentStep = 3"
                            OnEditSection="GoToStep"
                            OnSubmit="HandleSubmit"
                            IsSubmitting="@IsSubmitting"
                            ErrorMessage="@SubmitError" />
                break;
        }
    }
</div>

@code {
    private int CurrentStep;
    private bool IsSubmitted;
    private int ApplicationId;
    private bool IsSubmitting;
    private string? SubmitError;

    // Step 1 state
    private string PersonalFullName = "";
    private string PersonalEmail = "";
    private string PersonalPhone = "";
    private string PersonalAddress = "";

    // Step 2 state
    private List<WorkEntryModel> WorkEntries = new() { new("", "", DateTime.Today, null, "", false) };

    // Step 3 state
    private List<ReferenceModel> ReferenceEntries = new() { new("", "", "", ""), new("", "", "", "") };

    // Step 4 state
    private string CoverLetterText = "";

    private void GoToStep(int step)
    {
        if (step < CurrentStep)
            CurrentStep = step;
    }

    private Task<bool> ValidateEmailAsync(string email) =>
        ApplicationService.ValidateEmailAsync(email);

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        PersonalFullName = result.FullName;
        PersonalEmail = result.Email;
        PersonalPhone = result.Phone;
        PersonalAddress = result.Address;
        CurrentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryModel> entries)
    {
        WorkEntries = entries;
        CurrentStep = 2;
    }

    private void HandleWorkBack(List<WorkEntryModel> entries)
    {
        WorkEntries = entries;
        CurrentStep = 0;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        ReferenceEntries = refs;
        CurrentStep = 3;
    }

    private void HandleReferencesBack(List<ReferenceModel> refs)
    {
        ReferenceEntries = refs;
        CurrentStep = 1;
    }

    private void HandleCoverLetterNext(string text)
    {
        CoverLetterText = text;
        CurrentStep = 4;
    }

    private void HandleCoverLetterBack(string text)
    {
        CoverLetterText = text;
        CurrentStep = 2;
    }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        SubmitError = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(PersonalFullName, PersonalEmail, PersonalPhone, PersonalAddress),
                new WorkHistory(WorkEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
                ReferenceEntries.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                CoverLetterText
            );

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            SubmitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    private PersonalInfoStep.PersonalInfoResult GetPersonalResult() =>
        new(PersonalFullName, PersonalEmail, PersonalPhone, PersonalAddress);
}
