+.work-entry-header,
+.reference-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h4,
+.reference-header h4 {
+    margin: 0;
+    font-size: 1rem;
+    color: #495057;
+}
+
+/* Cover Letter */
+.cover-letter-input {
+    resize: vertical;
+    min-height: 200px;
+}
+
+.char-count {
+    display: block;
+    text-align: right;
+    font-size: 0.8rem;
+    color: #6c757d;
+    margin-top: 0.3rem;
+}
+
+.char-count.over-limit {
+    color: #dc3545;
+    font-weight: 600;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #e9ecef;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #1a1a2e;
+}
+
+.review-data {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.4rem 1rem;
+    margin: 0;
+}
+
+.review-data dt {
+    font-weight: 500;
+    color: #6c757d;
+    font-size: 0.85rem;
+}
+
+.review-data dd {
+    margin: 0;
+    font-size: 0.9rem;
+}
+
+.review-work-entry {
+    padding: 0.75rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.review-work-entry:last-child {
+    border-bottom: none;
+}
+
+.review-dates {
+    font-size: 0.8rem;
+    color: #6c757d;
+}
+
+.review-description {
+    margin: 0.4rem 0 0;
+    font-size: 0.85rem;
+    color: #495057;
+}
+
+.review-reference {
+    padding: 0.5rem 0;
+    font-size: 0.9rem;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    font-size: 0.9rem;
+    color: #495057;
+    line-height: 1.5;
+}
+
+/* Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 2rem;
+    background: white;
+    border: 1px solid #e9ecef;
+    border-radius: 8px;
+}
+
+.confirmation-icon {
+    width: 64px;
+    height: 64px;
+    border-radius: 50%;
+    background-color: #198754;
+    color: white;
+    font-size: 2rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin: 0 auto 1.5rem;
+}
+
+.submission-confirmation h2 {
+    color: #198754;
+    margin-bottom: 0.5rem;
+}
+
+.application-id {
+    margin-top: 1rem;
+    padding: 0.75rem;
+    background: #f8f9fa;
+    border-radius: 4px;
+    display: inline-block;
+}
+
+/* Responsive */
+@media (max-width: 600px) {
+    .form-row {
+        grid-template-columns: 1fr;
+    }
+
+    .step-indicator {
+        gap: 0.1rem;
+    }
+
+    .step {
+        min-width: 60px;
+        padding: 0.25rem;
+    }
+
+    .step-label {
+        font-size: 0.65rem;
+    }
+
+    .step-connector {
+        flex: 0 0 15px;
+    }
+}
